# v1.19 account functions override old single-account functions before event binding
block=r'''
    /* v1.19 multi-account manager */
    STORAGE.accounts='xauLab.accounts.v1'; STORAGE.activeAccount='xauLab.activeAccount.v1';
    state.accounts=[]; state.accountCreating=false;
    function persistAccountsV119(){try{localStorage.setItem(STORAGE.accounts,JSON.stringify(state.accounts||[]));if(state.account){localStorage.setItem(STORAGE.activeAccount,state.account.id);localStorage.setItem(STORAGE.account,JSON.stringify(state.account));}else{localStorage.removeItem(STORAGE.activeAccount);localStorage.removeItem(STORAGE.account);}}catch(e){}}
    function renderAccountMenu(){var box=byId('accountMenuList');if(!box)return;var xs=state.accounts||[];box.innerHTML=xs.length?xs.map(function(x){var on=state.account&&x.id===state.account.id;return '<div class="account-menu-row'+(on?' active':'')+'"><button type="button" data-account="'+escapeHtml(x.id)+'"><b>'+escapeHtml(x.name)+'</b><small dir="ltr">'+formatAccountMoney(x.balance)+' USD • 1:'+x.leverage+'</small></button><button type="button" class="del" data-del-account="'+escapeHtml(x.id)+'">×</button></div>';}).join(''):'<div class="account-menu-empty">No accounts yet</div>';}
    function loadAccount(){var xs=safeJsonParse(localStorage.getItem(STORAGE.accounts),null),old=sanitizeAccount(safeJsonParse(localStorage.getItem(STORAGE.account),null));state.accounts=Array.isArray(xs)?xs.map(sanitizeAccount).filter(Boolean):[];if(!state.accounts.length&&old)state.accounts=[old];var id=String(localStorage.getItem(STORAGE.activeAccount)||'');state.account=state.accounts.filter(function(x){return x.id===id;})[0]||state.accounts[0]||null;persistAccountsV119();syncAccountControls();updateAccountUi();renderAccountMenu();return state.account;}
    function persistAccountNow(){clearTimeout(state.accountPersistTimer);state.accountPersistTimer=null;if(state.account){state.account.updatedAt=Date.now();var hit=false;state.accounts=(state.accounts||[]).map(function(x){if(x.id===state.account.id){hit=true;return state.account;}return x;});if(!hit)state.accounts.push(state.account);}persistAccountsV119();renderAccountMenu();}
    function scheduleAccountPersist(){clearTimeout(state.accountPersistTimer);state.accountPersistTimer=setTimeout(persistAccountNow,180);}
    function updateAccountUi(){var x=state.account,s=byId('settingsAccountSummary'),tn=byId('tradeAccountName'),tm=byId('tradeAccountMeta'),hn=byId('historyAccountName'),hm=byId('historyAccountMeta');if(!x){if(s)s.textContent='No active account';if(tn)tn.textContent='No active account';if(tm)tm.textContent='Open Accounts to add or select';if(hn)hn.textContent='No active account';if(hm)hm.textContent='XAU Lab Demo';renderAccountMenu();return;}var meta='XAU Lab Demo • 1:'+x.leverage;if(s)s.textContent=x.name+' • '+formatAccountMoney(x.balance)+' USD • 1:'+x.leverage;if(tn)tn.textContent=x.name;if(tm)tm.textContent=meta;if(hn)hn.textContent=x.name;if(hm)hm.textContent=meta;renderAccountMenu();}
    function showAccountGate(editing,creating){state.accountEditing=!!editing;state.accountCreating=!!creating||(!state.account&&!editing);var x=state.accountCreating?null:state.account;byId('accountGateTitle').textContent=state.accountCreating?'إضافة حساب جديد':'إعدادات الحساب';byId('accountGateText').textContent=state.accountCreating?'أنشئ حساب Demo جديدًا، ثم بدّل بين حساباتك من Accounts أعلى الشارت.':'عدّل هذا الحساب فقط. تغيير رأس المال يعيد رصيده وسجله.';byId('accountName').value=x?x.name:'';byId('accountBalance').value=String(round(x?x.initialBalance:10000,2));byId('accountLeverage').value=String(x?x.leverage:100);byId('saveAccountButton').textContent=state.accountCreating?'إنشاء الحساب':'حفظ التعديلات';byId('cancelAccountEdit').classList.toggle('hidden',!state.accounts.length);byId('accountGate').classList.remove('hidden');document.body.classList.add('account-dialog-open');}
    function hideAccountGate(){if(!state.account&&!state.accounts.length)return;byId('accountGate').classList.add('hidden');document.body.classList.remove('account-dialog-open');state.accountEditing=false;state.accountCreating=false;}
    function saveAccountFromGate(){var name=byId('accountName').value.trim(),capital=Math.max(100,number(toEnglishDigits(byId('accountBalance').value),10000)),lev=clamp(Math.round(number(toEnglishDigits(byId('accountLeverage').value),100)),1,1000);if(!name){showToast('اكتب اسمًا للحساب','error');return;}var x=state.accountCreating?null:state.account,reset=!!(x&&Math.abs(x.initialBalance-capital)>.0001);if(!x){x=sanitizeAccount({id:'demo-'+Date.now()+'-'+Math.floor(Math.random()*9999),name:name,initialBalance:capital,balance:capital,equity:capital,freeMargin:capital,leverage:lev});state.accounts.push(x);state.account=x;}else{x.name=name;x.leverage=lev;if(reset){x.initialBalance=capital;x.balance=capital;x.equity=capital;x.freeMargin=capital;x.margin=0;x.floating=0;x.trades=[];x.manualPositions=[];x.pendingOrders=[];x.openTrade=null;}state.account=sanitizeAccount(x);}persistAccountNow();syncAccountControls();updateAccountUi();hideAccountGate();refreshManualOverlay(true);renderRobotTerminal();showToast(reset?'تم تحديث الحساب وإعادة ضبطه':'تم حفظ الحساب','success');}
    function switchAccountV119(id){persistAccountNow();var x=(state.accounts||[]).filter(function(a){return a.id===id;})[0];if(!x)return;state.account=x;state.lastResults=null;state.visualRobot=null;state.selectedManualTicket=null;persistAccountsV119();syncAccountControls();updateAccountUi();refreshManualOverlay(true);renderRobotTerminal();updateQuickTradeBar(currentManualQuote());showToast('Active: '+x.name,'success');}
    function deleteAccountV119(id){var x=(state.accounts||[]).filter(function(a){return a.id===id;})[0];if(!x)return;state.accounts=state.accounts.filter(function(a){return a.id!==id;});if(state.account&&state.account.id===id)state.account=state.accounts[0]||null;persistAccountsV119();syncAccountControls();updateAccountUi();refreshManualOverlay(true);renderRobotTerminal();showToast('تم حذف الحساب','success');}
    function saveQuickLotV119(){var i=byId('quickLot'),v=clamp(number(toEnglishDigits(i.value),state.account?state.account.lastLot:.10),.01,100);v=Math.round(v*100)/100;i.value=v.toFixed(2);if(state.account){state.account.lastLot=v;scheduleAccountPersist();}}
'''
j=R(j,'    function bindEvents() {',block+'\n    function bindEvents() {')
