j=R(j,"byId('editAccountButton').addEventListener('click', function () { showAccountGate(true); });","byId('editAccountButton').addEventListener('click',function(){showAccountGate(!!state.account,!state.account);});")
# readable light-mode errors
c+=r'''
/* v1.19 */
.lab-pane .meta-compact-toolbar{direction:ltr;justify-content:flex-start;gap:6px;padding:6px 8px}.lab-pane .timeframe-compact{margin-right:0}.account-tool{font-size:20px}.compact-quick-trade{min-height:56px;border-top:1px solid var(--line);grid-template-columns:minmax(0,1fr) 126px minmax(0,1fr)}.compact-quick-trade .quick-side{padding:6px 12px}.compact-quick-trade .quick-side strong{font-size:18px}.compact-quick-trade .quick-lot{grid-template-columns:32px 1fr 32px}.quick-lot label{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center}.quick-lot small{font:700 7px Arial;color:#65778a;letter-spacing:.7px}.quick-lot input{font-family:Arial,sans-serif!important;direction:ltr!important;font-variant-numeric:tabular-nums}.quick-lot button{font-family:Arial,sans-serif;font-size:21px}
.account-popover{position:absolute;z-index:130;top:52px;right:8px;width:min(300px,calc(100vw - 20px));max-height:55vh;overflow:auto;padding:7px;border:1px solid #31465d;border-radius:12px;background:#0b192a;box-shadow:0 14px 34px rgba(0,0,0,.38)}.account-popover-head{display:flex;direction:ltr;align-items:center;justify-content:space-between;padding:4px 4px 8px}.account-popover-head strong{color:#fff}.account-popover-head button{border:0;border-radius:8px;background:#2f80ed;color:#fff;padding:7px 10px;font-weight:800}.account-menu-row{display:grid;grid-template-columns:1fr 34px;gap:5px;margin:5px 0;padding:4px;border:1px solid #294158;border-radius:9px;background:#102238}.account-menu-row.active{border-color:#2f80ed}.account-menu-row>button:first-child{border:0;background:transparent;color:#eef4fa;text-align:right;padding:6px}.account-menu-row b,.account-menu-row small{display:block}.account-menu-row small{margin-top:3px;color:#8fa3b8;font:8px Arial}.account-menu-row .del{border:0;border-radius:7px;background:#341b25;color:#ff6c7d;font-size:18px}.account-menu-empty{padding:20px;text-align:center;color:#8fa3b8}.toast.error{color:#fff!important;background:#651b2a!important;border-color:#a84355!important;font-size:11px;font-weight:800}.toast.success{color:#fff!important;background:#0f5a48!important}body.light .toast.error,body.light .toast.success{color:#fff!important}body.light .account-popover{background:#fff;border-color:#ccd7e2}body.light .account-menu-row{background:#f4f7fa;border-color:#d7e0e8}body.light .account-menu-row>button:first-child{color:#18314b}
'''
